init.source:
function () {
            _super.prototype.execute.call(this);
            var encoders = [];
            if (this._history.getIsHistoryReplay() && !this._server.getInitResponse()) {
                encoders.push(new sgigame.HistoryReplayEncoder(this._history.getNextState()));
                this._history.restart();
            }
            var initData = new server.GLSRequest([]);
            this._server.makeInitRequest(initData);
        }

logic.source:
function () {
            _super.prototype.execute.call(this);
            var stateName = this._statesModel.getCurrentState().stateName;
            if ((stateName == sgigame.BaseGameStates.LOGIC_GLS_STATE) && !this._forceModel.forceOpen) {
                var history = this._history.getNextState();
                var encoders = [
                    this.getStakeEncode(),
                    new server.GLSCurrencyEncoder(this._server.getInitResponse().platformData.currencyMultiplier),
                ];
                if (history) {
                    encoders.push(new sgigame.HistoryReplayEncoder(history));
                }
                if (this._forceModel.forceSet) {
                    var forceEncoder = new sgigame.ForceEncoder(this._forceModel.reelData ? this._forceModel.reelData.positions : [0, 0, 0, 0, 0], this._forceModel.reelData ? this._forceModel.reelData.index : 0);
                    encoders.push(forceEncoder);
                }
                this._forceModel.forceSet = false;
                var data = new server.GLSRequest(encoders);
                this._server.makeLogicRequest(data);
            }
            else if (this._statesModel.getCurrentState().stateName == sgigame.PreGameStates.RECOVERY_STATE) {
                var encoders = [
                    this.getStakeEncode(),
                    new server.GLSCurrencyEncoder(this._server.getInitResponse().platformData.currencyMultiplier),
                ];
                var data = new server.GLSRequest(encoders);
                this._server.makeLogicRequest(data);
            }
        }

