money.source:
function (input, object) {
            var data = new sgigame.GameWinData();
            var node = input.getElementsByTagName("GameWinInfo")[0];
            if (node != null) {
                var attributes = node.attributes;
                var nodeChildren = node.childNodes;
                data.totalWagerWin = parseInt(attributes.getNamedItem("totalWagerWin").value);
                data.totalBGWin = parseInt(attributes.getNamedItem("totalBGWin").value);
                data.totalFSWin = parseInt(attributes.getNamedItem("totalFSWin").value);
                data.maxWin = parseInt(attributes.getNamedItem("maxWinValue").value);
                data.isMaxWin = attributes.getNamedItem("isMaxWin").value === "Y";
            }
            object.gameWinData = data;
        }

free.source:
function (input, object) {
            var data;
            var node = input.getElementsByTagName("Feature")[0];
            //  var node1: Node = input.getElementsByTagName("GameResult")[0];
            if (node != null) {
                var attributes = node.attributes;
                if (attributes.getNamedItem("name")) {
                    data = new sgigame.FsData();
                    var dataNode = node.childNodes[0];
                    var dataAttr = dataNode.attributes;
                    if (dataAttr.getNamedItem("fsReTriggered")) {
                        data.firstSpin = false;
                        data.expandedWildReel = [];
                        data.totalFreeSpinsWin = parseInt(dataAttr.getNamedItem("totalFSTriggered").value);
                        data.remainingFreeSpins = parseInt(dataAttr.getNamedItem("remainingFS").value);
                        data.freeSpinType = attributes.getNamedItem("name").value;
                        if (data.freeSpinType != sgigame.GameConfig.fgType[0]) {
                            data.matchFourSymbols = [];
                            var matchFourSymbols = dataAttr.getNamedItem("matchFourSymbols").value.split(",");
                            for (var i = 0; i < matchFourSymbols.length; i++) {
                                var mat = matchFourSymbols[i].split('|').map(Number);
                                var matSymbol = { reelId: mat[0], symbolId: mat[1] };
                                data.matchFourSymbols.push(matSymbol);
                            }
                        }
                        data.freeSpinsReTriggered = parseInt(dataAttr.getNamedItem("fsReTriggered").value);
                        data.lastSpin = (dataAttr.getNamedItem("lastFreeSpin").value === "Y");
                        var baseRecovery = input.getElementsByTagName("BaseGameRecoveryInfo")[0];
                        data.bgReelStops = baseRecovery.getElementsByTagName("ReelStops")[0].textContent.split("|").map(Number);
                    }
                    else {
                        data.firstSpin = true;
                        data.freeSpinType = attributes.getNamedItem("name").value;
                        data.remainingFreeSpins = parseInt(dataAttr.getNamedItem("totalFSTriggered").value);
                        data.totalFreeSpinsAwarded = parseInt(dataAttr.getNamedItem("totalFSTriggered").value);
                        data.freeSpinsReTriggered = 0;
                        data.lastSpin = false;
                        if (data.freeSpinType != sgigame.GameConfig.fgType[0]) {
                            data.matchFourSymbols = [];
                            var matchFourSymbols = dataAttr.getNamedItem("matchFourSymbols").value.split(",");
                            for (var i = 0; i < matchFourSymbols.length; i++) {
                                var mat = matchFourSymbols[i].split('|').map(Number);
                                var matSymbol = { reelId: mat[0], symbolId: mat[1] };
                                data.matchFourSymbols.push(matSymbol);
                            }
                        }
                    }
                }
            }
            object.fsData = data;
            this.parseRecoveryFsData(input, object);
        }

freeRecovery.source:
function (input, object) {
            var data;
            var node = input.getElementsByTagName("BaseGameRecoveryInfo")[0];
            if (node != null) {
                var attributes = node.attributes;
                var nodeChildren = node.childNodes;
                var featureNode;
                for (var i = 0; i < nodeChildren.length; ++i) {
                    if (nodeChildren[i].nodeName == "Feature") {
                        featureNode = nodeChildren[i];
                        break;
                    }
                }
                if (featureNode) {
                    attributes = featureNode.attributes;
                    if (attributes.getNamedItem("name") || attributes.getNamedItem("name").value.toLowerCase() === "freegame") {
                        data = new sgigame.FsData();
                        var dataNode = featureNode.childNodes[0];
                        var dataAttr = dataNode.attributes;
                        data.firstSpin = true;
                        data.freeSpinType = attributes.getNamedItem("name").value;
                        data.remainingFreeSpins = parseInt(dataAttr.getNamedItem("totalFSTriggered").value);
                        data.totalFreeSpinsAwarded = parseInt(dataAttr.getNamedItem("totalFSTriggered").value);
                        data.freeSpinsReTriggered = 0;
                        data.lastSpin = false;
                    }
                }
            }
            object.recoveryFsData = data;
        }

next.source:
function () {
            var _this = this;
            _super.prototype.execute.call(this);
            var logicResponse = this._server.getLogicResponse();
            if (this.isFreeGame()) {
                if (!this.isLastFreeGame())
                    this._statesModel.gotoNextState();
                else if (logicResponse.gameWinData.totalFSWin == 0) {
                    this._statesModel.changeStateByName(sgigame.BaseGameStates.CONTINUE_PAYLINE_WINS_STATE);
                    this.eventDispatcher.dispatchEvent(new sgigame.GameEvent(sgigame.GameEvent.EXIT_FREESPINS));
                    this._audio.StopBonusLoopSound();
                }
                else {
                    TweenMax.delayedCall(1.5, function () {
                        _this._statesModel.changeStateByName(sgigame.BaseGameStates.FREESPIN_OUTRO_STATE);
                    }, [], this);
                }
            }
            else {
                this._statesModel.changeStateByName(sgigame.BaseGameStates.END_GLS_STATE);
            }
        }

